  elsif v_new = 1 then
    if not exists (select 1 from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'advanced' and scope = 'final' and module_key is null and ord = 42 and not active and md5(prompt || chr(31) || options::text || chr(31) || answer_index::text || chr(31) || coalesce(explanation, '')) = 'a75eb8feeb421a9b4f937da53d7a6675') then
