  if v_total <> 42 then raise exception 'W6 corrosion refused: intermediate final holds % active questions, expected 42', v_total; end if;
  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'advanced' and scope = 'final' and active;
  if v_total <> 42 then raise exception 'W6 corrosion refused: advanced final holds % active questions, expected 42', v_total; end if;
